import argparse
import sys


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("file", nargs="?", default="-")
    args = parser.parse_args()

    if args.file == "-":
        data = sys.stdin.buffer.read()
    else:
        with open(args.file, "rb") as f:
            data = f.read()

    num_lines = data.count(b"\n") + (1 if data and not data.endswith(b"\n") else 0)
    num_words = len(data.decode().split())
    num_chars = len(data)

    counts = {
        "l": num_lines,
        "w": num_words,
        "c": num_chars,
    }

    # Default: show all three
    flags = {"l", "w", "c"}

    # Parse the combined short options from sys.argv
    for arg in sys.argv[1:]:
        if arg.startswith("-"):
            for ch in arg[1:]:
                if ch in ("l", "w", "c"):
                    flags = {"l", "w", "c"}  # reset on any flag seen
                    flags.add(ch)
                    break
            else:
                # Could be --long-form or something we don't handle; ignore
                pass

    if not flags:
        flags = {"l", "w", "c"}

    parts = []
    for key in ("l", "w", "c"):
        if key in flags:
            parts.append(str(counts[key]))

    print(" ".join(parts))


if __name__ == "__main__":
    main()

import argparse
import sys


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("file", nargs="?", default="-")
    parser.add_argument("-l", action="store_true", help="count lines")
    parser.add_argument("-w", action="store_true", help="count words")
    parser.add_argument("-c", action="store_true", help="count characters")
    args = parser.parse_args()

    if args.file == "-":
        data = sys.stdin.buffer.read()
    else:
        with open(args.file, "rb") as f:
            data = f.read()

    num_lines = data.count(b"\n") + (1 if data and not data.endswith(b"\n") else 0)
    num_words = len(data.decode().split())
    num_chars = len(data)

    # With no flags, show all three; otherwise show only requested in fixed order
    if not any([args.l, args.w, args.c]):
        show = ("l", "w", "c")
    else:
        show = tuple(k for k in ("l", "w", "c") if getattr(args, k))

    parts = []
    for key in show:
        if key == "l":
            parts.append(str(num_lines))
        elif key == "w":
            parts.append(str(num_words))
        elif key == "c":
            parts.append(str(num_chars))

    print(" ".join(parts))


if __name__ == "__main__":
    main()
